insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Dashboard','Allocable payroll','=SUM(''Monthly Engine''!G5:G10)','Sum allocable payroll across the six monthly engine rows.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Dashboard','Direct project cost','=SUM(''Monthly Engine''!I5:I10)','Sum direct project cost across months.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Dashboard','Administration cost','=SUM(''Monthly Engine''!J5:J10)','Sum administration cost across months.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Dashboard','Unrecovered cost','=SUM(''Monthly Engine''!K5:K10)','Sum the remaining allocable cost after direct and admin allocations.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Dashboard','Average readiness','=AVERAGE(''Monthly Engine''!Q5:Q10)','Average monthly weighted readiness score.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Dashboard','Months ready to post','=COUNTIF(''Monthly Engine''!S5:S10,"READY TO POST")','Count months where the critical posting gate passes.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Time Entry','Month','=DATE(YEAR(B5),MONTH(B5),1)','Normalize each entry date to the first day of its month.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Time Entry','Daily Total','=SUMIFS($H$5:$H$600,$B$5:$B$600,B5,$D$5:$D$600,D5,$J$5:$J$600,"Finance approved")','Sum finance-approved hours for the same employee and date.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Time Entry','Daily Check','=IF(ABS(N5-SUMIFS(Calendar!$E$5:$E$200,Calendar!$A$5:$A$200,B5))<0.01,"PASS","REVIEW")','Compare daily approved hours to standard hours from Calendar.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Time Entry','Project Eligibility','=IF(COUNTIFS(Projects!$A$5:$A$100,F5,Projects!$F$5:$F$100,"Active",Projects!$D$5:$D$100,"<="&B5,Projects!$E$5:$E$100,">="&B5,Projects!$I$5:$I$100,D5)>0,"PASS","BLOCK")','Project must be active, date-valid, and assigned to the employee.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Time Entry','AI Coding Check','=IF(AND(K5=F5,M5="Accepted"),"PASS","REVIEW")','AI suggestion must match selected project and be explicitly accepted.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Time Entry','Entry Assurance','=IF(AND(H5>0,H5<=24,MOD(H5,0.25)=0,O5="PASS",P5="PASS",Q5="PASS"),"PASS","REVIEW")','Hours must be positive, <=24, quarter-hour aligned, and all entry-level controls must pass.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Payroll','Allocable Cost','=C5+D5+E5-F5','Basic salary + benefits + statutory cost − exclusions.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Calendar','Recorded Hours','=SUMIFS(''Time Entry''!$H$5:$H$600,''Time Entry''!$B$5:$B$600,A5,''Time Entry''!$J$5:$J$600,"Finance approved")','Sum finance-approved hours for the date.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Calendar','Variance','=F5-E5','Recorded hours − standard hours.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Calendar','Daily Status','=IF(ABS(G5)<0.01,"PASS",IF(AND(E5=0,F5=0),"PASS","REVIEW"))','Pass when variance is zero, including valid zero-hour non-working days; otherwise review.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Expected Hours','=SUMIFS(Calendar!$E$5:$E$200,Calendar!$B$5:$B$200,A5)','Sum standard hours for the month.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Recorded Hours','=SUMIFS(''Time Entry''!$H$5:$H$600,''Time Entry''!$C$5:$C$600,A5,''Time Entry''!$J$5:$J$600,"Finance approved")','Sum finance-approved time for the month.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Direct Hours','=SUMIFS(''Time Entry''!$H$5:$H$600,''Time Entry''!$C$5:$C$600,A5,''Time Entry''!$I$5:$I$600,"Direct project",''Time Entry''!$J$5:$J$600,"Finance approved")','Monthly finance-approved direct-project hours.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Admin Hours','=SUMIFS(''Time Entry''!$H$5:$H$600,''Time Entry''!$C$5:$C$600,A5,''Time Entry''!$I$5:$I$600,"Administration",''Time Entry''!$J$5:$J$600,"Finance approved")','Monthly finance-approved administration hours.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Hours Variance','=C5-B5','Recorded hours − expected hours.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Allocable Cost','=SUMIFS(Payroll!$G$5:$G$20,Payroll!$A$5:$A$20,A5,Payroll!$B$5:$B$20,"E001")','Employee allocable payroll cost for the month.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Hourly Cost','=IFERROR(G5/B5,0)','Allocable cost ÷ expected hours.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Direct Cost','=D5*H5','Direct hours × hourly cost.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Admin Cost','=E5*H5','Admin hours × hourly cost.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Unrecovered Cost','=G5-I5-J5','Allocable cost − direct cost − admin cost.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Completeness','=IFERROR(MIN(1,C5/B5),0)','Recorded ÷ expected, capped at 100%.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Daily Reconciliation','=IFERROR(COUNTIFS(Calendar!$B$5:$B$200,A5,Calendar!$E$5:$E$200,">0",Calendar!$H$5:$H$200,"PASS")/COUNTIFS(Calendar!$B$5:$B$200,A5,Calendar!$E$5:$E$200,">0"),0)','Share of working days with a PASS daily reconciliation.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Eligibility','=IFERROR(COUNTIFS(''Time Entry''!$C$5:$C$600,A5,''Time Entry''!$P$5:$P$600,"PASS")/COUNTIF(''Time Entry''!$C$5:$C$600,A5),0)','Share of monthly entries passing project eligibility.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Timeliness','=1','Pilot assumption fixed at 100%; replace with a production timeliness control.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Approval','=IF(COUNTIFS(''Time Entry''!$C$5:$C$600,A5,''Time Entry''!$J$5:$J$600,"<>Finance approved")=0,1,0)','Pass only if every monthly entry is finance approved.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Readiness Score','=35%*L5+25%*M5+15%*N5+15%*O5+10%*P5','Weighted score: 35% completeness + 25% daily reconciliation + 15% eligibility + 15% timeliness + 10% approval.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Critical Exceptions','=IF(ABS(F5)>0.01,1,0)+COUNTIFS(''Time Entry''!$C$5:$C$600,A5,''Time Entry''!$P$5:$P$600,"BLOCK")+COUNTIFS(''Time Entry''!$C$5:$C$600,A5,''Time Entry''!$J$5:$J$600,"<>Finance approved")','Count variance gate + eligibility blocks + unapproved entries.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Posting Status','=IF(AND(ABS(F5)<0.01,R5=0),"READY TO POST","BLOCKED")','Posting allowed only when hours variance is zero and critical exceptions equal zero.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Source Hours','=SUMIFS(Checks!$C$5:$C$10,Checks!$A$5:$A$10,A5)','Source timesheet hours brought from Checks for reconciliation.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Source Reconciliation','=C5-T5','Recorded hours − source hours; must equal zero.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Monthly Engine','Recovery Rate','=IFERROR(I5/G5,0)','Direct project cost ÷ allocable payroll cost.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Checks','Calculated','=''Monthly Engine''!C5','Pull calculated recorded hours from Monthly Engine.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Checks','Delta','=D5-C5','Calculated hours − source target.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Checks','Result','=IF(ABS(E5)<0.01,"PASS","FAIL")','Source reconciliation passes when delta is zero.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Checks','MODEL STATUS','=IF(AND(COUNTIF(G5:G10,"FAIL")=0,COUNTIF(''Monthly Engine''!S5:S10,"BLOCKED")=0),"PASS","FAIL")','Overall model passes only when source checks pass and no month is blocked.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Checks','Blocked Months','=COUNTIF(''Monthly Engine''!S5:S10,"BLOCKED")','Count blocked monthly engine rows.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Checks','Configuration Status','=IF(COUNTIF(Payroll!I5:I10,"REVIEW")=0,"COMPLETE","REVIEW")','Payroll configuration must have no REVIEW statuses.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Voucher Status','=INDEX(''Monthly Engine''!$S$5:$S$10,MATCH(B5,''Monthly Engine''!$A$5:$A$10,0))','Use selected month posting status.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Approved Project Hours','=SUMIFS(''Time Entry''!$H$5:$H$600,''Time Entry''!$C$5:$C$600,$B$5,''Time Entry''!$F$5:$F$600,$B$6,''Time Entry''!$J$5:$J$600,"Finance approved")','Finance-approved hours for the selected project and month.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Raw Cost','=C12*E12','Approved project hours × monthly hourly cost.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Recoverable Amount','=IF($B$8="READY TO POST",MIN(F12,G12),0)','Recoverable amount is zero unless month is ready; then lower of raw cost and budget ceiling.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Monthly hours variance control','=IF(ABS(B16)<0.01,"PASS","FAIL")','Fail if selected month has non-zero hour variance.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Critical exceptions control','=IF(B17=0,"PASS","FAIL")','Fail if selected month has any critical exceptions.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Source reconciliation control','=IF(ABS(B18)<0.01,"PASS","FAIL")','Fail if source reconciliation is non-zero.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Payroll configuration control','=IF(B19="COMPLETE","PASS","REVIEW")','Review until payroll components are fully configured.');
insert into public.workbook_formula_catalog(sheet_name,field_name,excel_formula,application_logic) values ('Voucher','Posting authorization','=IF(B20="READY TO POST","PASS","BLOCKED")','Post only if selected monthly status is READY TO POST.');
insert into public.workbook_engine_metadata(key,value) values ('foundation','{"source_file": "ADRA_Recovery_Assurance_Engine_Prototype.xls", "pilot_period": "2026-01 through 2026-06", "time_records": 471, "formula_rules": 52, "engine": "JavaScript deterministic workbook formula engine"}'::jsonb) on conflict(key) do update set value=excluded.value,updated_at=now();
